// @ts-check
'use strict';

const { kotlinCommands } = require('./commands');
const { constantName, kotlinIdentifier, kotlinString, memberName } = require('./names');

/** @typedef {import('./read').Model} Model */
/** @typedef {import('./read').Field} Field */
/** @typedef {import('./read').NativeScreenModel} NativeScreenModel */
/** @typedef {import('../config').AndroidKind} AndroidKind */

/** The package of the generated file: the navigation finds the list of screens in it by name. */
const PACKAGE = 'dev.apexnative.navigation.generated';

const HEADER = `// Generated by \`npx apex-navigation codegen\` from the native screens of the app. Don't edit it: change the props in
// TypeScript and run the command again.`;

/**
 * The Kotlin file of the app's native screens: their props, the screen and navigation types their views take, and the
 * list the navigation registers as it starts. A screen with a `kind` is registered: its composable (Compose) or class
 * (Android views) is `<Name>Screen` in the package `<app package>.screens`.
 * @param {{ screen: NativeScreenModel; kind?: AndroidKind }[]} screens
 * @param {{ appPackage: string; commands?: import('./read').CommandScreenModel[] }} options `commands`: the
 *   screens of `screens` for the typed commands, which come after the rest
 * @returns {string}
 */
function kotlinFile(screens, { appPackage, commands = [] }) {
  const compose = screens.some(({ kind }) => kind === 'compose');
  const imports = [
    ...(compose
      ? [
          'androidx.compose.runtime.getValue',
          'androidx.compose.runtime.mutableStateOf',
          'androidx.compose.runtime.setValue',
          'androidx.compose.ui.platform.ComposeView',
        ]
      : []),
    'dev.apexnative.navigation.NavigationApplication',
    'dev.apexnative.navigation.nativescreen.NativeScreenContext',
    'kotlin.coroutines.resume',
    'kotlin.coroutines.resumeWithException',
    'kotlinx.coroutines.suspendCancellableCoroutine',
    'org.json.JSONArray',
    'org.json.JSONObject',
  ];
  return [
    HEADER,
    '',
    `package ${PACKAGE}`,
    '',
    imports.map((name) => `import ${name}`).join('\n'),
    '',
    registry(screens, appPackage),
    ...screens.map(({ screen }) => props(screen)),
    shared(compose),
    ...(commands.length > 0 ? [kotlinCommands(commands)] : []),
  ].join('\n');
}

/**
 * @param {{ screen: NativeScreenModel; kind?: AndroidKind }[]} screens
 * @param {string} appPackage
 */
function registry(screens, appPackage) {
  const registered = screens.flatMap(({ screen, kind }) => {
    if (!kind) return [];
    const name = screen.nativeName;
    const view = `${appPackage}.screens.${name}Screen`;
    const value = `NativeScreen(context, ::${name}Props)`;
    return [
      `    application.registerNativeScreen(${kotlinString(name)}) { activity, context ->`,
      ...(kind === 'compose'
        ? [`      ComposeView(activity).apply { setContent { ${view}(${value}) } }`]
        : [`      ${view}(activity, ${value}).view`]),
      '    }',
    ];
  });
  return `/** The native screens of the app, which the navigation registers itself as it starts. */
object ApexNavigationGeneratedScreens {
  @JvmStatic
  fun register(application: NavigationApplication) {
${registered.length > 0 ? registered.join('\n') : '    // None: `npx apex-navigation screen <Name> --native` adds one.'}
  }
}
`;
}

/**
 * The props of one screen: a data class with its enums and objects inside, read from the screen's context.
 * @param {NativeScreenModel} screen
 */
function props(screen) {
  const name = `${screen.nativeName}Props`;
  const parameters = screen.fields.flatMap((field) => [
    ...docLines(field.doc, '  '),
    `  val ${kotlinIdentifier(field.name)}: ${declaredType(field)},`,
  ]);
  const reads = screen.fields.map(
    (field) =>
      `    ${kotlinIdentifier(field.name)} = ${
        field.type.kind !== 'function'
          ? read(field, `context.props.opt(${kotlinString(field.name)})`)
          : field.optional
            ? `if (${kotlinString(field.name)} in context.functions) (${call(field.name, field.type)}) else null`
            : call(field.name, field.type)
      },`
  );
  const enums = screen.enums.map(
    (item) => `  enum class ${item.name}(val value: String) {
${item.values.map((value) => `    ${constantName(value)}(${kotlinString(value)}),`).join('\n')}
  }
`
  );
  const objects = screen.objects.map((object) => {
    const fields = object.fields.map(
      (field) => `    val ${kotlinIdentifier(field.name)}: ${declaredType(field)},`
    );
    const objectReads = object.fields.map(
      (field) =>
        `        ${kotlinIdentifier(field.name)} = ${read(field, `fields.opt(${kotlinString(field.name)})`)},`
    );
    const json = object.fields.map(
      (field) =>
        `.put(${kotlinString(field.name)}, ${encode(field.type, kotlinIdentifier(field.name), field.optional)})`
    );
    return `  data class ${object.name}(
${fields.join('\n')}
  ) {
    fun json(): JSONObject = JSONObject()${json.join('')}

    companion object {
      fun read(value: Any?): ${object.name} {
        val fields = Decode.obj(value)
        return ${object.name}(
${objectReads.join('\n')}
        )
      }
    }
  }
`;
  });
  const nested = [...enums, ...objects];
  return `/** The props of the native screen \`${screen.nativeName}\` (${screen.file}). */
data class ${name}(
${parameters.join('\n')}
) {
  constructor(context: NativeScreenContext) : this(
${reads.join('\n')}
  )
${nested.length > 0 ? '\n' + nested.join('\n') : ''}}
`;
}

/**
 * @param {Field} field
 */
function declaredType(field) {
  const type = kotlinType(field.type);
  if (!field.optional) return type;
  return field.type.kind === 'function' ? `(${type})?` : `${type}?`;
}

/**
 * @param {Model} model
 * @returns {string}
 */
function kotlinType(model) {
  switch (model.kind) {
    case 'string':
      return 'String';
    case 'number':
      return model.int ? 'Int' : 'Double';
    case 'boolean':
      return 'Boolean';
    case 'enum':
    case 'object':
      return model.name;
    case 'array':
      return `List<${kotlinType(model.element)}>`;
    case 'function':
      return `suspend (${model.parameters.map(({ type }) => kotlinType(type)).join(', ')}) -> ${
        model.result ? kotlinType(model.result) : 'Unit'
      }`;
  }
}

/**
 * The expression that reads a field from a value of JS.
 * @param {Field} field
 * @param {string} value
 */
function read(field, value) {
  return field.optional
    ? `if (Decode.present(${value})) ${decode(field.type, value)} else null`
    : decode(field.type, value);
}

/**
 * @param {Model} model
 * @param {string} value
 * @returns {string}
 */
function decode(model, value) {
  switch (model.kind) {
    case 'string':
      return `Decode.string(${value})`;
    case 'number':
      return model.int ? `Decode.int(${value})` : `Decode.number(${value})`;
    case 'boolean':
      return `Decode.bool(${value})`;
    case 'enum':
      return `Decode.string(${value}).let { raw -> ${model.name}.entries.firstOrNull { it.value == raw } ?: ${model.name}.entries[0] }`;
    case 'object':
      return `${model.name}.read(${value})`;
    case 'array':
      return `Decode.list(${value}) { ${decode(model.element, 'it')} }`;
    case 'function':
      return 'null';
  }
}

/**
 * The value JS gets for a value of Kotlin: an argument of a function, or a field of an object.
 * @param {Model} model
 * @param {string} value
 * @param {boolean} [optional]
 * @returns {string}
 */
function encode(model, value, optional = false) {
  if (optional) return `(${value}?.let { ${encode(model, 'it')} } ?: JSONObject.NULL)`;
  switch (model.kind) {
    case 'enum':
      return `${value}.value`;
    case 'object':
      return `${value}.json()`;
    case 'array':
      return `JSONArray(${value}.map { ${encode(model.element, 'it')} })`;
    default:
      return value;
  }
}

/**
 * A function of the props: a lambda that calls it in JS with its arguments and reads what it resolved with.
 * @param {string} name
 * @param {Extract<Model, { kind: 'function' }>} model
 */
function call(name, model) {
  const parameters = model.parameters.map(({ name: parameter }) =>
    kotlinIdentifier(memberName(parameter))
  );
  const head = parameters.length > 0 ? `${parameters.join(', ')} -> ` : '';
  const args = model.parameters
    .map(({ type }, index) => `, ${encode(type, parameters[index])}`)
    .join('');
  const called = `context.callJs(${kotlinString(name)}${args})`;
  const body = model.result ? decode(model.result, called) : `${called}; Unit`;
  return `{ ${head}${body} }`;
}

/**
 * @param {string | undefined} doc
 * @param {string} indent
 */
function docLines(doc, indent) {
  return doc ? [`${indent}/** ${doc.replace(/\n/g, ' ')} */`] : [];
}

/**
 * The screen and navigation types, and the helpers that read plain data from JS.
 * @param {boolean} compose the props of a Compose screen are state that composes it again
 */
function shared(compose) {
  const propsDeclaration = compose
    ? `  /** The props as they are now; a composable that reads them composes again when they change. */
  var props: Props by mutableStateOf(decode(context))
    private set`
    : `  /** The props as they are now; [onChange] tells when they change. */
  var props: Props = decode(context)
    private set`;
  return `/** What a native screen gets: its props, which it shows again when they change, and the navigation from it. */
class NativeScreen<Props>(val context: NativeScreenContext, private val decode: (NativeScreenContext) -> Props) {
${propsDeclaration}

  /** The commands of the navigation from this screen. */
  val navigation = ScreenNavigation(context)

  private val listeners = mutableListOf<(Props) -> Unit>()

  init {
    context.onPropsChange = {
      props = decode(context)
      listeners.forEach { listener -> listener(props) }
    }
  }

  /** Called on the main thread with the new props, each time they change. */
  fun onChange(listener: (Props) -> Unit) {
    listeners += listener
  }
}

/** The commands of the navigation from a native screen. They run in JS, as \`useNavigation()\` of a React screen does. */
class ScreenNavigation(private val context: NativeScreenContext) {
  /** Shows a screen over this one in its stack; returns the id of the screen shown. */
  suspend fun push(screen: String, props: Map<String, Any?> = emptyMap()): String =
    context.navigateJs("push", screen, JSONObject().put("props", JSONObject(props))) as? String ?: ""

  /** Shows a screen over everything, in a stack of its own. */
  suspend fun showModal(screen: String, props: Map<String, Any?> = emptyMap()): String =
    context.navigateJs("showModal", screen, JSONObject().put("props", JSONObject(props))) as? String ?: ""

  /** Shows a screen over everything, without taking the place of any. */
  suspend fun showOverlay(screen: String, props: Map<String, Any?> = emptyMap()): String =
    context.navigateJs("showOverlay", screen, JSONObject().put("props", JSONObject(props))) as? String ?: ""

  /** Shows a screen in a column of the split view this screen is in. */
  suspend fun showInColumn(screen: String, props: Map<String, Any?> = emptyMap()): String =
    context.navigateJs("showInColumn", screen, JSONObject().put("props", JSONObject(props))) as? String ?: ""

  /** Goes back to the screen before this one in its stack. */
  suspend fun pop() {
    context.navigateJs("pop")
  }

  /** Goes back to a screen of this stack, by its id. */
  suspend fun popTo(screenId: String) {
    context.navigateJs("popTo", screenId)
  }

  /** Goes back to the first screen of this stack. */
  suspend fun popToRoot() {
    context.navigateJs("popToRoot")
  }

  /** Closes the modal or the overlay this screen is in. */
  suspend fun dismiss() {
    context.navigateJs("dismiss")
  }

  /** Changes the options of this screen. */
  suspend fun setOptions(options: Map<String, Any?>) {
    context.navigateJs("setOptions", JSONObject(options))
  }

  /** Selects a tab of the tabs this screen is in, by its index. */
  suspend fun selectTab(index: Int) {
    context.navigateJs("selectTab", index)
  }

  /** Selects a tab of the tabs this screen is in, by its id. */
  suspend fun selectTab(id: String) {
    context.navigateJs("selectTab", id)
  }

  /** The badge of this screen's tab; null takes it away. */
  suspend fun setTabBadge(badge: String?) {
    context.navigateJs("setTabBadge", badge)
  }
}

private suspend fun NativeScreenContext.callJs(function: String, vararg arguments: Any?): Any? =
  suspendCancellableCoroutine { continuation ->
    call(function, JSONArray(arguments.toList())) { result ->
      result.fold({ continuation.resume(it) }, { continuation.resumeWithException(it) })
    }
  }

private suspend fun NativeScreenContext.navigateJs(command: String, vararg arguments: Any?): Any? =
  suspendCancellableCoroutine { continuation ->
    navigate(command, JSONArray(arguments.toList())) { result ->
      result.fold({ continuation.resume(it) }, { continuation.resumeWithException(it) })
    }
  }

/** Plain data from JS. */
private object Decode {
  fun present(value: Any?) = value != null && value != JSONObject.NULL

  fun string(value: Any?) = value as? String ?: ""

  fun number(value: Any?) = (value as? Number)?.toDouble() ?: 0.0

  fun int(value: Any?) = (value as? Number)?.toInt() ?: 0

  fun bool(value: Any?) = value as? Boolean ?: false

  fun obj(value: Any?) = value as? JSONObject ?: JSONObject()

  fun <T> list(value: Any?, item: (Any?) -> T): List<T> =
    (value as? JSONArray)?.let { array -> (0 until array.length()).map { item(array.opt(it)) } } ?: emptyList()
}
`;
}

module.exports = { kotlinFile, PACKAGE };
